const url = 'https://demo.realworld.show/';
const maxAttempts = 3;
const pauseMs = 2000;

let result = null;

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  const start = Date.now();
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 20000,
    });

    const statusCode = Number(res.statusCode ?? 0);
    const body =
      typeof res.body === 'string'
        ? res.body
        : JSON.stringify(res.body ?? '');
    const responseTimeMs = Date.now() - start;
    const looksLikeConduit =
      body.toLowerCase().includes('conduit') ||
      body.toLowerCase().includes('realworld');

    result = {
      url,
      attempt,
      maxAttempts,
      statusCode,
      responseTimeMs,
      ok: statusCode === 200 && looksLikeConduit,
      checkedAt: new Date().toISOString(),
    };

    if (result.ok) break;
  } catch (error) {
    result = {
      url,
      attempt,
      maxAttempts,
      statusCode: 0,
      responseTimeMs: Date.now() - start,
      ok: false,
      error: error.message || String(error),
      checkedAt: new Date().toISOString(),
    };
  }

  if (attempt < maxAttempts && result && !result.ok) {
    await new Promise((r) => setTimeout(r, pauseMs));
  }
}

if (!result) {
  result = {
    url,
    attempt: maxAttempts,
    maxAttempts,
    statusCode: 0,
    responseTimeMs: 0,
    ok: false,
    error: 'No result from health check',
    checkedAt: new Date().toISOString(),
  };
}

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.checks)) store.checks = [];
store.checks.push({
  checkedAt: result.checkedAt,
  ok: result.ok,
  statusCode: result.statusCode,
  responseTimeMs: result.responseTimeMs,
});
if (store.checks.length > 500) {
  store.checks = store.checks.slice(-500);
}

return [
  {
    json: {
      ...result,
      totalInStore: store.checks.length,
    },
  },
];

const check = $input.first().json;

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.checks)) {
  store.checks = [];
}

store.checks.push({
  checkedAt: check.checkedAt,
  ok: !!check.ok,
  statusCode: check.statusCode,
  responseTimeMs: check.responseTimeMs,
});

if (store.checks.length > 500) {
  store.checks = store.checks.slice(-500);
}

return [
  {
    json: {
      ...check,
      recorded: true,
      totalInStore: store.checks.length,
    },
  },
];

const store = $getWorkflowStaticData('global');
const checks = Array.isArray(store.checks) ? store.checks : [];

const now = Date.now();
const since = now - 24 * 60 * 60 * 1000;

const recent = checks.filter((c) => {
  const t = new Date(c.checkedAt).getTime();
  return !Number.isNaN(t) && t >= since;
});

const total = recent.length;
const failures = recent.filter((c) => !c.ok);
const failCount = failures.length;
const successCount = total - failCount;
const uptimePct =
  total === 0 ? 100 : Math.round((successCount / total) * 1000) / 10;

let avgMs = 0;
if (total > 0) {
  avgMs = Math.round(
    recent.reduce((sum, c) => sum + (Number(c.responseTimeMs) || 0), 0) /
      total
  );
}

const content = [
  '📊 **Uptime summary (demo.realworld.show)**',
  'Window: last 24 hours',
  `Checks: ${total} (stored total: ${checks.length})`,
  `Failures: ${failCount}`,
  `Uptime: ${uptimePct}%`,
  `Avg response: ${avgMs} ms`,
].join('\n');

return [
  {
    json: {
      content,
      hasData: total > 0,
      total,
      totalInStore: checks.length,
    },
  },
];
